pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up a concrete scenario: deploy a contract that does nothing (or just use a non-existent address via low-level call)
        // We'll use an empty address that will cause the call to fail (address with no code)
        address nonExistent = address(0x1234);
        bytes memory dummyData = "";

        // Try calling forward - in reference version it reverts, in bug version it doesn't
        bool ok;
        try c.forward(nonExistent, dummyData) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference would require the call to succeed, so it reverts -> ok == false
        // The modified version does not require, so it succeeds -> ok == true
        // Thus we assert the reference behavior (ok == false)
        assertTrue(!ok);
    }
}

// Note: In the reference, require(_s) causes revert on failed call, so ok becomes false
// In the bug version, the call returns (false, 0x) but no revert, so ok becomes true
// Our assertion !ok holds for reference (false) and breaks for bug (true)

