    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address target = address(0x1234);
        vm.deal(target, 1 wei);
        bytes memory data = hex"";
        // This will revert on reference (require(_s) fails because target has no code)
        // In modified version, it silently succeeds
        vm.prank(target);
        c.forward(target, data);
        assertEq(address(c).balance, 0);
    }
}

