pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy helper contract that will set owner on the target via delegatecall
        Helper helper = new Helper();
        // Use delegatecall through helper to mutate storage
        address ownerBefore = c.owner();
        bytes memory payload = abi.encodeWithSignature("setOwner()");
        bool ok;
        try c.forward(address(helper), payload) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
        // Reference: call does not change owner; bug: delegatecall changes owner to helper
        address ownerAfter = c.owner();
        assertEq(ownerAfter, ownerBefore);
    }
}

contract Helper {
    function setOwner() external {
        // This runs in context of C when delegatecalled
        assembly {
            sstore(0, caller())
        }
    }
}

