pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a helper contract that selfdestructs
        SelfDestructHelper helper = new SelfDestructHelper();
        address callee = address(helper);

        // Owner sends 1 ether to C
        vm.deal(address(this), 1 ether);
        vm.prank(address(this));
        (bool sent, ) = address(c).call{value: 1 ether}("");
        require(sent, "send failed");

        // Record initial balance of C
        uint256 balanceBefore = address(c).balance;

        // Call forward with the selfdestruct helper
        bytes memory data = abi.encodeWithSignature("die()");
        c.forward(callee, data);

        // In reference (call), C's balance stays 1 ether
        // In bug (delegatecall), the selfdestruct consumes C's balance --> becomes 0
        assertEq(address(c).balance, balanceBefore);
    }
}

contract SelfDestructHelper {
    function die() public {
        selfdestruct(payable(address(0)));
    }
}

