contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a helper contract that will modify storage slot 0 (owner)
        // when called via delegatecall
        address attacker = address(new Attacker());
        // attacker has no code that returns, but we just need the external call;
        // For delegatecall, attacker's code will run in C's context
        // We create a simple attacker that writes to slot 0
        // Since we cannot define another contract? Actually we can define Attacker in same file?
        // No, the rules say define no other contract. So we deploy a pre-computed bytecode that writes to slot 0.
        // Better: use vm.etch to place code at an address
        address malicious;
        malicious = address(0x1234);
        // Bytecode: SLOAD(0) PUSH1 0x42 SSTORE(0) STOP
        bytes memory code = hex"60008054806042905500";
        vm.etch(malicious, code);
        // Now call forward on reference version with .call -> nothing happens to owner
        // On bugged version with .delegatecall -> owner becomes 0x42
        // We need to catch revert: forward doesn't revert in either version if call succeeds
        // But note: the reference version uses .call, so it returns success; attacker code returns nothing
        // Actually our bytecode writes to slot 0 and then STOP, which returns nothing but success
        // So no revert. 
        // But original C's forward expects success; both will succeed.
        // Then we check owner via getter (public) after the call
        address originalOwner = address(this); // from setUp, msg.sender
        c.forward(malicious, "");
        // Reference version keeps originalOwner; bugged version changes owner to 0x42
        // However address type cannot be 0x42; we wrote 0x42 as uint160? Actually SSTORE stores bytes32
        // Let's write a simpler test: use an existing contract that does something observable
        // Simpler: deploy a helper that returns a value via delegatecall and check that value
        // But the property must be observable via public surface. Owner is not public!
        // Let's read the code: owner is private, no getter. So cannot observe directly.
        // We need another approach.
        // The important observable difference: delegatecall modifies C's storage (owner) which can
        // affect subsequent calls that depend on owner. But owner is not public, so we cannot read it.
        // So we need a different scenario.
        // Let's fallback to checking balance? No.
        // Actually the only public surface is address(c).balance and any public functions.
        // There are no public functions besides forward.
        // So the only observable is address(c).balance if we send ether? But delegatecall doesn't affect balance.
        // This approach fails because owner is private.
    }
}

