pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: fund the contract with 1 ether
        vm.deal(address(c), 1 ether);

        // Deploy a callee that will overwrite storage slot 0 (owner) with address(this)
        address attacker = address(0x1234);
        vm.deal(attacker, 0);
        vm.prank(attacker);

        // The callee's code: sstore(0, address(this)) to overwrite owner
        bytes memory maliciousCode = hex"60806040523360005500"; // PUSH1 0x40 MSTORE... simplified: just sstore(0, caller)
        address callee;
        assembly {
            callee := create(0, add(maliciousCode, 0x20), mload(maliciousCode))
        }

        // Call forward - in reference version (call) this should NOT modify owner
        // In buggy version (delegatecall) it WILL set owner to callee
        c.forward(callee, "");

        // Now try to forward a call that would send ether from contract
        // If owner is still original (reference), sending to original owner works
        // If owner is overwritten (bug), sending to original owner fails

        // Create a simple receiver
        address receiver = address(0x5678);
        vm.deal(receiver, 0);

        // Try to forward a call that sends 0.5 ether to receiver
        // In reference: owner is msg.sender (original deployer), so this succeed
        // In buggy: owner is now 0x1234 (callee), so this will fail
        bytes memory sendData = abi.encodeWithSignature("callvalue()");
        bool success;
        try c.forward(receiver, sendData) {
            success = true;
        } catch {
            success = false;
        }
        assertTrue(success);
    }
}

