        address target = address(0x1234);
        vm.etch(target, hex"608060405260043610603f5760003560e01c8063a3a3de54146043578063b69ef8a81460605750600080fd5b348015604e57600080fd5b506001600160a01b03811633146083565b348015606b57600080fd5b5060736080565b60405190815260200160405180910390f35b604051806020016040528060008152509056fe");
        vm.deal(target, 0);
        // Give contract C some ether to forward
        vm.deal(address(c), 1 ether);
        // Prepare data for a call that transfers 1 wei to target (the receive function)
        bytes memory data = abi.encodeWithSignature("receive()");
        // Call forward on reference version doesn't revert; on modified it reverts
        // We try-catch to capture the revert
        bool ok;
        vm.prank(address(0xdead));
        try c.forward{value: 0}(target, data) {
